		// this avoids some copying
		// it might crash when freeing the bitmap but we never do
129			for (y = 0; y < DOOMGENERIC_RESY; y++) {
			temp_bitmap->line[y] = (unsigned char *) &DG_ScreenBuffer[y * DOOMGENERIC_RESX];
