#!/usr/bin/env node
// MIPS32r2 (o32, little-endian) userspace interpreter for doomgeneric_mips.
// Implements the Linux-style syscall ABI the binary uses (v0=number using
// x86-64 syscall numbers, args in a0..a2, result in v0).
'use strict';
const fs = require('fs');
const path = require('path');

const ELF_PATH = process.argv[2] || path.join(__dirname, 'doomgeneric_mips');

// ---------------------------------------------------------------------------
// Memory
// ---------------------------------------------------------------------------
// bss reaches ~0x404b1790 (contains a 1GB static heap); give room for a stack.
const MEM_SIZE = 0x41000000; // ~1.09 GB
const mem = new Uint8Array(MEM_SIZE);

function ru8(a){ return mem[a]; }
function r8(a){ return (mem[a]<<24)>>24; }
function ru16(a){ return mem[a] | (mem[a+1]<<8); }
function r16(a){ return ((mem[a] | (mem[a+1]<<8))<<16)>>16; }
function r32(a){ return (mem[a] | (mem[a+1]<<8) | (mem[a+2]<<16) | (mem[a+3]<<24)); }
function ru32(a){ return r32(a)>>>0; }
function w8(a,v){ mem[a]=v; }
function w16(a,v){ mem[a]=v; mem[a+1]=v>>8; }
function w32(a,v){ mem[a]=v; mem[a+1]=v>>8; mem[a+2]=v>>16; mem[a+3]=v>>24; }

// ---------------------------------------------------------------------------
// ELF loader
// ---------------------------------------------------------------------------
function loadElf(file){
  const d = fs.readFileSync(file);
  if(d[0]!==0x7f||d[1]!==0x45||d[2]!==0x4c||d[3]!==0x46) throw new Error('not ELF');
  const entry = d.readUInt32LE(24);
  const phoff = d.readUInt32LE(28);
  const phentsize = d.readUInt16LE(42);
  const phnum = d.readUInt16LE(44);
  for(let i=0;i<phnum;i++){
    const o = phoff + i*phentsize;
    const type = d.readUInt32LE(o);
    if(type!==1) continue; // PT_LOAD
    const off = d.readUInt32LE(o+4);
    const vaddr = d.readUInt32LE(o+8);
    const filesz = d.readUInt32LE(o+16);
    const memsz = d.readUInt32LE(o+20);
    for(let j=0;j<filesz;j++) mem[vaddr+j] = d[off+j];
    // remaining (bss) already zero.
  }
  return entry;
}

const entry = loadElf(ELF_PATH);

// ---------------------------------------------------------------------------
// CPU state
// ---------------------------------------------------------------------------
const r = new Int32Array(32);
let hi = 0, lo = 0;
const fpr = new Int32Array(32);
let fcc = 0;

// gp / sp setup
r[28] = 0x0047d090 | 0;      // gp (from .reginfo)
r[29] = 0x40f00000 | 0;      // sp
r[31] = 0;

// float conversion scratch
const cvB = new ArrayBuffer(8);
const cvI = new Int32Array(cvB);
const cF32 = new Float32Array(cvB);
const cF64 = new Float64Array(cvB);
function getS(i){ cvI[0]=fpr[i]; return cF32[0]; }
function setS(i,v){ cF32[0]=v; fpr[i]=cvI[0]; }
function getD(i){ cvI[0]=fpr[i]; cvI[1]=fpr[i+1]; return cF64[0]; }
function setD(i,v){ cF64[0]=v; fpr[i]=cvI[0]; fpr[i+1]=cvI[1]; }

// ---------------------------------------------------------------------------
// Syscalls (Linux x86-64 numbers, MIPS register convention)
// ---------------------------------------------------------------------------
const C = fs.constants;
const fdInfo = new Map(); // hostFd -> { pos }
let running = true;
let exitCode = 0;

function readCString(addr){
  let s = '';
  for(;;){ const b = mem[addr++]; if(b===0) break; s += String.fromCharCode(b); }
  return s;
}

function doOpen(pathAddr, gflags, mode){
  const p = readCString(pathAddr);
  let f;
  const acc = gflags & 3;
  if(acc===0) f = C.O_RDONLY; else if(acc===1) f = C.O_WRONLY; else f = C.O_RDWR;
  if(gflags & 64) f |= C.O_CREAT;
  if(gflags & 128) f |= C.O_EXCL;
  if(gflags & 512) f |= C.O_TRUNC;
  if(gflags & 1024) f |= C.O_APPEND;
  try{
    const fd = fs.openSync(p, f, mode ? (mode & 0o777) : 0o644);
    fdInfo.set(fd, { pos: 0 });
    return fd;
  }catch(e){ return -2; }
}

function doRead(fd, buf, count){
  if(fd===0) return 0; // stdin: EOF
  const info = fdInfo.get(fd);
  if(!info) return -9;
  const b = Buffer.allocUnsafe(count);
  let n;
  try{ n = fs.readSync(fd, b, 0, count, info.pos); }catch(e){ return -5; }
  for(let i=0;i<n;i++) mem[buf+i] = b[i];
  info.pos += n;
  return n;
}

function doWrite(fd, buf, count){
  if(fd===1 || fd===2){
    const b = Buffer.from(mem.subarray(buf, buf+count));
    if(fd===1) process.stdout.write(b); else process.stderr.write(b);
    return count;
  }
  const info = fdInfo.get(fd);
  if(!info) return -9;
  const b = Buffer.from(mem.subarray(buf, buf+count));
  let n;
  try{ n = fs.writeSync(fd, b, 0, count, info.pos); }catch(e){ return -5; }
  info.pos += n;
  return n;
}

function doLseek(fd, off, whence){
  const info = fdInfo.get(fd);
  if(!info) return -9;
  let np;
  if(whence===0) np = off;
  else if(whence===1) np = info.pos + off;
  else { let sz=0; try{ sz = fs.fstatSync(fd).size; }catch(e){} np = sz + off; }
  info.pos = np;
  return np;
}

function syscall(){
  const num = r[2]>>>0;
  const a0 = r[4], a1 = r[5], a2 = r[6];
  let ret = 0;
  switch(num){
    case 0: ret = doRead(a0>>>0, a1>>>0, a2>>>0); break;                 // read
    case 1: ret = doWrite(a0|0, a1>>>0, a2>>>0); break;                  // write
    case 2: ret = doOpen(a0>>>0, a1|0, a2|0); break;                     // open
    case 3: {                                                            // close
      const fd = a0|0;
      if(fd>2 && fdInfo.has(fd)){ try{ fs.closeSync(fd); }catch(e){} fdInfo.delete(fd); }
      ret = 0; break;
    }
    case 8: ret = doLseek(a0|0, a1|0, a2|0); break;                      // lseek
    case 74: ret = 0; break;                                            // fsync
    case 82: {                                                          // rename
      try{ fs.renameSync(readCString(a0>>>0), readCString(a1>>>0)); ret=0; }catch(e){ ret=-2; } break;
    }
    case 83: {                                                          // mkdir
      try{ fs.mkdirSync(readCString(a0>>>0), a1 & 0o777); ret=0; }catch(e){ ret = (e && e.code==='EEXIST') ? -17 : -2; } break;
    }
    case 87: {                                                          // unlink
      try{ fs.unlinkSync(readCString(a0>>>0)); ret=0; }catch(e){ ret=-2; } break;
    }
    case 35: ret = 0; break;                                            // nanosleep
    case 201: {                                                         // time
      const sec = Math.floor(Date.now()/1000);
      if(a0>>>0) w32(a0>>>0, sec);
      ret = sec; break;
    }
    case 60: running = false; exitCode = a0|0; return;                  // exit
    default:
      process.stderr.write('vm: unhandled syscall '+num+'\n');
      ret = -38; break;
  }
  r[2] = ret|0;
}

// ---------------------------------------------------------------------------
// signed 64-bit multiply helper -> sets hi/lo
// ---------------------------------------------------------------------------
function mult(a,b){
  const aL=a&0xffff, aH=a>>>16, bL=b&0xffff, bH=b>>>16;
  const ll=aL*bL, lh=aL*bH, hl=aH*bL, hh=aH*bH;
  const mid=(ll>>>16)+(lh&0xffff)+(hl&0xffff);
  lo=((ll&0xffff)|((mid&0xffff)<<16))|0;
  let h=(hh+(lh>>>16)+(hl>>>16)+(mid>>>16))|0;
  if(a<0) h=(h-(b>>>0))|0;
  if(b<0) h=(h-(a>>>0))|0;
  hi=h;
}
function multu(a,b){
  const aL=a&0xffff, aH=a>>>16, bL=b&0xffff, bH=b>>>16;
  const ll=aL*bL, lh=aL*bH, hl=aH*bL, hh=aH*bH;
  const mid=(ll>>>16)+(lh&0xffff)+(hl&0xffff);
  lo=((ll&0xffff)|((mid&0xffff)<<16))|0;
  hi=(hh+(lh>>>16)+(hl>>>16)+(mid>>>16))|0;
}

// ---------------------------------------------------------------------------
// Main interpreter loop
// ---------------------------------------------------------------------------
let pc = entry|0, npc = (entry+4)|0;

function run(){
while(running){
  r[0]=0;
  const inst = ru32(pc);
  let nextNpc = (npc+4)|0;
  const op = inst>>>26;
  const rs = (inst>>21)&31;
  const rt = (inst>>16)&31;
  const rd = (inst>>11)&31;
  const sa = (inst>>6)&31;
  const funct = inst&63;

  switch(op){
    case 0x00: { // SPECIAL
      switch(funct){
        case 0x00: if(rd) r[rd]=r[rt]<<sa; break; // sll
        case 0x02: // srl / rotr
          if((inst>>21)&1){ const s=sa; if(rd) r[rd]= s? ((r[rt]>>>s)|(r[rt]<<(32-s))) : r[rt]; }
          else if(rd) r[rd]=r[rt]>>>sa; break;
        case 0x03: if(rd) r[rd]=r[rt]>>sa; break; // sra
        case 0x04: if(rd) r[rd]=r[rt]<<(r[rs]&31); break; // sllv
        case 0x06: { const s=r[rs]&31; // srlv / rotrv
          if((inst>>6)&1){ if(rd) r[rd]= s? ((r[rt]>>>s)|(r[rt]<<(32-s))) : r[rt]; }
          else if(rd) r[rd]=r[rt]>>>s; break; }
        case 0x07: if(rd) r[rd]=r[rt]>>(r[rs]&31); break; // srav
        case 0x08: nextNpc=r[rs]; break; // jr
        case 0x09: { const t=r[rs]; if(rd) r[rd]=(npc+4)|0; nextNpc=t; break; } // jalr
        case 0x0a: if(r[rt]===0){ if(rd) r[rd]=r[rs]; } break; // movz
        case 0x0b: if(r[rt]!==0){ if(rd) r[rd]=r[rs]; } break; // movn
        case 0x0c: syscall(); break; // syscall
        case 0x0d: syscall(); break; // break (treat as trap->ignore) ; actually 0x0d=break
        case 0x10: if(rd) r[rd]=hi; break; // mfhi
        case 0x11: hi=r[rs]; break; // mthi
        case 0x12: if(rd) r[rd]=lo; break; // mflo
        case 0x13: lo=r[rs]; break; // mtlo
        case 0x18: mult(r[rs],r[rt]); break; // mult
        case 0x19: multu(r[rs],r[rt]); break; // multu
        case 0x1a: { const a=r[rs],b=r[rt]; if(b===0){lo=0;hi=0;} else {lo=(Math.trunc(a/b))|0; hi=(a%b)|0;} break; } // div
        case 0x1b: { const a=r[rs]>>>0,b=r[rt]>>>0; if(b===0){lo=0;hi=0;} else {lo=(Math.trunc(a/b))|0; hi=(a%b)|0;} break; } // divu
        case 0x20: if(rd) r[rd]=(r[rs]+r[rt])|0; break; // add
        case 0x21: if(rd) r[rd]=(r[rs]+r[rt])|0; break; // addu
        case 0x22: if(rd) r[rd]=(r[rs]-r[rt])|0; break; // sub
        case 0x23: if(rd) r[rd]=(r[rs]-r[rt])|0; break; // subu
        case 0x24: if(rd) r[rd]=r[rs]&r[rt]; break; // and
        case 0x25: if(rd) r[rd]=r[rs]|r[rt]; break; // or
        case 0x26: if(rd) r[rd]=r[rs]^r[rt]; break; // xor
        case 0x27: if(rd) r[rd]=~(r[rs]|r[rt]); break; // nor
        case 0x2a: if(rd) r[rd]=(r[rs]<r[rt])?1:0; break; // slt
        case 0x2b: if(rd) r[rd]=((r[rs]>>>0)<(r[rt]>>>0))?1:0; break; // sltu
        case 0x34: break; // teq -> ignore trap
        case 0x30: case 0x31: case 0x32: case 0x33: case 0x36: break; // tge/tgeu/tlt/tltu/tne -> ignore
        default: throw new Error('SPECIAL funct 0x'+funct.toString(16)+' @0x'+pc.toString(16));
      }
      break;
    }
    case 0x01: { // REGIMM
      const off=((inst&0xffff)<<16>>16);
      switch(rt){
        case 0x00: if(r[rs]<0) nextNpc=(npc+(off<<2))|0; break; // bltz
        case 0x01: if(r[rs]>=0) nextNpc=(npc+(off<<2))|0; break; // bgez
        case 0x10: r[31]=(npc+4)|0; if(r[rs]<0) nextNpc=(npc+(off<<2))|0; break; // bltzal
        case 0x11: r[31]=(npc+4)|0; if(r[rs]>=0) nextNpc=(npc+(off<<2))|0; break; // bgezal
        default: throw new Error('REGIMM rt 0x'+rt.toString(16)+' @0x'+pc.toString(16));
      }
      break;
    }
    case 0x02: nextNpc=((pc & 0xf0000000) | ((inst&0x3ffffff)<<2))|0; break; // j
    case 0x03: r[31]=(npc+4)|0; nextNpc=((pc & 0xf0000000) | ((inst&0x3ffffff)<<2))|0; break; // jal
    case 0x04: if(r[rs]===r[rt]) nextNpc=(npc+(((inst&0xffff)<<16>>16)<<2))|0; break; // beq
    case 0x05: if(r[rs]!==r[rt]) nextNpc=(npc+(((inst&0xffff)<<16>>16)<<2))|0; break; // bne
    case 0x06: if(r[rs]<=0) nextNpc=(npc+(((inst&0xffff)<<16>>16)<<2))|0; break; // blez
    case 0x07: if(r[rs]>0) nextNpc=(npc+(((inst&0xffff)<<16>>16)<<2))|0; break; // bgtz
    case 0x08: if(rt) r[rt]=(r[rs]+((inst&0xffff)<<16>>16))|0; break; // addi
    case 0x09: if(rt) r[rt]=(r[rs]+((inst&0xffff)<<16>>16))|0; break; // addiu
    case 0x0a: if(rt) r[rt]=(r[rs]<((inst&0xffff)<<16>>16))?1:0; break; // slti
    case 0x0b: if(rt) r[rt]=((r[rs]>>>0)<((((inst&0xffff)<<16>>16))>>>0))?1:0; break; // sltiu
    case 0x0c: if(rt) r[rt]=r[rs]&(inst&0xffff); break; // andi
    case 0x0d: if(rt) r[rt]=r[rs]|(inst&0xffff); break; // ori
    case 0x0e: if(rt) r[rt]=r[rs]^(inst&0xffff); break; // xori
    case 0x0f: if(rt) r[rt]=(inst&0xffff)<<16; break; // lui
    case 0x1c: { // SPECIAL2
      switch(funct){
        case 0x02: if(rd) r[rd]=Math.imul(r[rs],r[rt]); break; // mul
        case 0x00: { mult(r[rs],r[rt]); break; } // madd (approx: recompute) -> handled below
        case 0x20: { let x=r[rs]>>>0,n=0; if(x===0)n=32; else{ while(!(x&0x80000000)){x<<=1;n++;} } if(rd) r[rd]=n; break; } // clz
        case 0x21: { let x=~r[rs]>>>0,n=0; if(x===0)n=32; else{ while(!(x&0x80000000)){x<<=1;n++;} } if(rd) r[rd]=n; break; } // clo
        default: throw new Error('SPECIAL2 funct 0x'+funct.toString(16)+' @0x'+pc.toString(16));
      }
      break;
    }
    case 0x1f: { // SPECIAL3
      if(funct===0x00){ // ext
        const pos=sa, size=rd+1;
        const mask = size>=32 ? 0xffffffff : ((1<<size)-1);
        if(rt) r[rt]=(r[rs]>>>pos)&mask; break;
      } else if(funct===0x04){ // ins
        const pos=sa, msb=rd, size=msb-pos+1;
        const m = (size>=32?0xffffffff:((1<<size)-1))<<pos;
        if(rt) r[rt]=((r[rt] & ~m) | ((r[rs]<<pos)&m))|0; break;
      } else if(funct===0x20){ // BSHFL
        const sub=(inst>>6)&0x1f;
        if(sub===0x02){ const v=r[rt]; if(rd) r[rd]=(((v&0x00ff00ff)<<8)|((v>>>8)&0x00ff00ff))|0; } // wsbh
        else if(sub===0x10){ if(rd) r[rd]=(r[rt]<<24)>>24; } // seb
        else if(sub===0x18){ if(rd) r[rd]=(r[rt]<<16)>>16; } // seh
        else throw new Error('BSHFL sub 0x'+sub.toString(16));
        break;
      } else throw new Error('SPECIAL3 funct 0x'+funct.toString(16)+' @0x'+pc.toString(16));
    }
    case 0x20: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; if(rt) r[rt]=r8(a); break; } // lb
    case 0x21: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; if(rt) r[rt]=r16(a); break; } // lh
    case 0x22: { // lwl
      const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; const al=a&~3; const b=a&3;
      const w=r32(al); const sh=(3-b)*8; const mask=(1<<sh)-1;
      if(rt) r[rt]=((w<<sh)|(r[rt]&mask))|0; break;
    }
    case 0x23: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; if(rt) r[rt]=r32(a); break; } // lw
    case 0x24: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; if(rt) r[rt]=ru8(a); break; } // lbu
    case 0x25: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; if(rt) r[rt]=ru16(a); break; } // lhu
    case 0x26: { // lwr
      const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; const al=a&~3; const b=a&3;
      const w=r32(al);
      if(b===0){ if(rt) r[rt]=w; }
      else { const sh=b*8; const mask=(0xffffffff<<(32-sh))|0; if(rt) r[rt]=((r[rt]&mask)|(w>>>sh))|0; }
      break;
    }
    case 0x28: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; w8(a,r[rt]); break; } // sb
    case 0x29: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; w16(a,r[rt]); break; } // sh
    case 0x2a: { // swl
      const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; const al=a&~3; const b=a&3;
      const w=r32(al); const sh=(3-b)*8; const keep=((b+1)*8>=32)?0:((0xffffffff<<((b+1)*8))|0);
      w32(al, ((w&keep)|(r[rt]>>>sh))|0); break;
    }
    case 0x2b: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; w32(a,r[rt]); break; } // sw
    case 0x2e: { // swr
      const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; const al=a&~3; const b=a&3;
      const w=r32(al); const sh=b*8; const keep=(b===0)?0:((1<<sh)-1);
      w32(al, ((w&keep)|(r[rt]<<sh))|0); break;
    }
    case 0x31: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; fpr[rt]=r32(a); break; } // lwc1
    case 0x35: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; fpr[rt]=r32(a); fpr[rt+1]=r32(a+4); break; } // ldc1
    case 0x39: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; w32(a,fpr[rt]); break; } // swc1
    case 0x3d: { const a=(r[rs]+((inst&0xffff)<<16>>16))>>>0; w32(a,fpr[rt]); w32(a+4,fpr[rt+1]); break; } // sdc1
    case 0x11: { // COP1
      const fmt=rs; const ft=rt; const fs=rd; const fd=sa;
      if(fmt===0){ if(rt) r[rt]=fpr[fs]; } // mfc1 (gpr=rt field)
      else if(fmt===4){ fpr[fs]=r[rt]; } // mtc1
      else if(fmt===3){ if(rt) r[rt]=fpr[fs+1]; } // mfhc1
      else if(fmt===7){ fpr[fs+1]=r[rt]; } // mthc1
      else if(fmt===2){ if(rt) r[rt]=0; } // cfc1 (fcsr) - stub
      else if(fmt===6){ } // ctc1 - stub
      else if(fmt===8){ // bc1
        const off=((inst&0xffff)<<16>>16); const tf=ft&1;
        if((fcc?1:0)===tf) nextNpc=(npc+(off<<2))|0;
      }
      else if(fmt===16){ // single
        switch(funct){
          case 0x00: setS(fd,getS(fs)+getS(ft)); break;
          case 0x01: setS(fd,getS(fs)-getS(ft)); break;
          case 0x02: setS(fd,getS(fs)*getS(ft)); break;
          case 0x03: setS(fd,getS(fs)/getS(ft)); break;
          case 0x04: setS(fd,Math.sqrt(getS(fs))); break;
          case 0x05: setS(fd,Math.abs(getS(fs))); break;
          case 0x06: setS(fd,getS(fs)); break;
          case 0x07: setS(fd,-getS(fs)); break;
          case 0x0d: fpr[fd]=Math.trunc(getS(fs))|0; break; // trunc.w.s
          case 0x21: setD(fd,getS(fs)); break; // cvt.d.s
          case 0x24: fpr[fd]=Math.trunc(getS(fs))|0; break; // cvt.w.s
          case 0x11: { const tf=ft&1; if((fcc?1:0)===tf) setS(fd,getS(fs)); break; } // movcf
          default:
            if(funct>=0x30){ const a=getS(fs),b=getS(ft); const un=(a!==a||b!==b); const lt=a<b, eq=a===b; fcc=((un&&(funct&1))||(eq&&(funct&2))||(lt&&(funct&4)))?1:0; break; }
            throw new Error('COP1.S funct 0x'+funct.toString(16)+' @0x'+pc.toString(16));
        }
      }
      else if(fmt===17){ // double
        switch(funct){
          case 0x00: setD(fd,getD(fs)+getD(ft)); break;
          case 0x01: setD(fd,getD(fs)-getD(ft)); break;
          case 0x02: setD(fd,getD(fs)*getD(ft)); break;
          case 0x03: setD(fd,getD(fs)/getD(ft)); break;
          case 0x04: setD(fd,Math.sqrt(getD(fs))); break;
          case 0x05: setD(fd,Math.abs(getD(fs))); break;
          case 0x06: setD(fd,getD(fs)); break;
          case 0x07: setD(fd,-getD(fs)); break;
          case 0x20: setS(fd,getD(fs)); break; // cvt.s.d
          case 0x24: fpr[fd]=Math.trunc(getD(fs))|0; break; // cvt.w.d
          case 0x11: { const tf=ft&1; if((fcc?1:0)===tf) setD(fd,getD(fs)); break; } // movcf
          default:
            if(funct>=0x30){ const a=getD(fs),b=getD(ft); const un=(a!==a||b!==b); const lt=a<b, eq=a===b; fcc=((un&&(funct&1))||(eq&&(funct&2))||(lt&&(funct&4)))?1:0; break; }
            throw new Error('COP1.D funct 0x'+funct.toString(16)+' @0x'+pc.toString(16));
        }
      }
      else if(fmt===20){ // word
        switch(funct){
          case 0x20: setS(fd, fpr[fs]|0); break; // cvt.s.w
          case 0x21: setD(fd, fpr[fs]|0); break; // cvt.d.w
          default: throw new Error('COP1.W funct 0x'+funct.toString(16));
        }
      }
      else throw new Error('COP1 fmt 0x'+fmt.toString(16)+' @0x'+pc.toString(16));
      break;
    }
    default:
      throw new Error('opcode 0x'+op.toString(16)+' @0x'+pc.toString(16));
  }

  pc = npc;
  npc = nextNpc;
}
}

try{
  run();
}catch(e){
  process.stderr.write('vm: '+(e && e.stack ? e.stack : e)+'\n');
  process.exit(1);
}
process.exit(exitCode);
